{
    // Test with zero
    uint16_t zero16 = 0;
    uint16_t dst16 = 0xFFFF;
    endianCopy(zero16, dst16);
    EXPECT_EQ(dst16, 0);

    // Test with max
    uint16_t max16 = 0xFFFF;
    uint16_t dst16max = 0;
    endianCopy(max16, dst16max);
    EXPECT_EQ(dst16max, 0xFFFF); // All bits set, swap doesn't change
